-- What a new character knows (EzTonguesCharDB.known). UnitRace's file name -> its languages; Horde characters
-- also know Orcish and warlocks Demonic. Alliance common is plain Common (what you type), so there's nothing to add.
ns.RACE_TONGUES = {
    Dwarf = { "dwarvish" },
    NightElf = { "darnassian" },
    Gnome = { "gnomish" },
    Orc = { "orcish" },
    Scourge = { "gutterspeak" },
    Undead = { "gutterspeak" },
    Tauren = { "taurahe" },
    Troll = { "zandali" },
    BloodElf = { "thalassian" },
}
ns.FACTION_TONGUE = { Horde = "orcish" }
ns.CLASS_TONGUE = { WARLOCK = "demonic" }

